     1→/**
     2→ * Enhanced Routes for Visualizer and Video NFT Features
     3→ */
     4→
     5→import { Express, Request, Response } from "express";
     6→import { visualizerService } from "./services/visualizerService";
     7→import { videoNFTService } from "./services/videoNFTService";
     8→import { jesusCartelService } from "./services/jesusCartelService";
     9→import multer from "multer";
    10→import path from "path";
    11→
    12→// Configure multer for audio uploads
    13→const upload = multer({
    14→  dest: "/tmp/uploads",
    15→  limits: { fileSize: 200 * 1024 * 1024 } // 200MB
    16→});
    17→
    18→export function setupEnhancedRoutes(app: Express) {
    19→  /**
    20→   * Generate video visualizer for audio
    21→   * POST /api/visualizer/generate
    22→   */
    23→  app.post("/api/visualizer/generate", upload.single("audio"), async (req: Request, res: Response) => {
    24→    try {
    25→      const audioPath = req.file?.path || req.body.audioPath;
    26→      if (!audioPath) {
    27→        return res.status(400).json({ error: "Audio file required" });
    28→      }
    29→
    30→      const options = {
    31→        style: req.body.style || "music_video",
    32→        genre: req.body.genre,
    33→        artist: req.body.artist,
    34→        title: req.body.title,
    35→        width: parseInt(req.body.width) || 1024,
    36→        height: parseInt(req.body.height) || 1024,
    37→        frames: parseInt(req.body.frames) || 120,
    38→        seed: parseInt(req.body.seed) || -1,
    39→        comfyui_url: req.body.comfyui_url || process.env.COMFYUI_URL
    40→      };
    41→
    42→      const job = await visualizerService.generateVideo(audioPath, options);
    43→
    44→      res.json({
    45→        success: true,
    46→        job_id: job.job_id,
    47→        status: job.status,
    48→        message: "Video generation started",
    49→        check_status: `/api/visualizer/status/${job.job_id}`
    50→      });
    51→
    52→    } catch (error: any) {
    53→      console.error("Visualizer generation error:", error);
    54→      res.status(500).json({
    55→        error: "Failed to generate visualizer",
    56→        message: error.message
    57→      });
    58→    }
    59→  });
    60→
    61→  /**
    62→   * Get visualizer job status
    63→   * GET /api/visualizer/status/:job_id
    64→   */
    65→  app.get("/api/visualizer/status/:job_id", (req: Request, res: Response) => {
    66→    const { job_id } = req.params;
    67→    const job = visualizerService.getJobStatus(job_id);
    68→
    69→    if (!job) {
    70→      return res.status(404).json({ error: "Job not found" });
    71→    }
    72→
    73→    res.json(job);
    74→  });
    75→
    76→  /**
    77→   * Get all visualizer jobs
    78→   * GET /api/visualizer/jobs
    79→   */
    80→  app.get("/api/visualizer/jobs", (req: Request, res: Response) => {
    81→    const jobs = visualizerService.getAllJobs();
    82→    res.json({ jobs, count: jobs.length });
    83→  });
    84→
    85→  /**
    86→   * Mint video NFT
    87→   * POST /api/nft/video/mint
    88→   */
    89→  app.post("/api/nft/video/mint", async (req: Request, res: Response) => {
    90→    try {
    91→      const {
    92→        videoPath,
    93→        thumbnailPath,
    94→        title,
    95→        artist,
    96→        description,
    97→        duration,
    98→        network,
    99→        walletId,
   100→        attributes
   101→      } = req.body;
   102→
   103→      if (!videoPath || !title || !artist || !network || !walletId) {
   104→        return res.status(400).json({
   105→          error: "Missing required fields: videoPath, title, artist, network, walletId"
   106→        });
   107→      }
   108→
   109→      const result = await videoNFTService.mintVideoNFT({
   110→        videoPath,
   111→        thumbnailPath,
   112→        title,
   113→        artist,
   114→        description,
   115→        duration,
   116→        network,
   117→        walletId,
   118→        attributes
   119→      });
   120→
   121→      res.json(result);
   122→
   123→    } catch (error: any) {
   124→      console.error("Video NFT minting error:", error);
   125→      res.status(500).json({
   126→        error: "Failed to mint video NFT",
   127→        message: error.message
   128→      });
   129→    }
   130→  });
   131→
   132→  /**
   133→   * Get video NFT details
   134→   * GET /api/nft/video/:network/:contractAddress/:tokenId
   135→   */
   136→  app.get("/api/nft/video/:network/:contractAddress/:tokenId", async (req: Request, res: Response) => {
   137→    try {
   138→      const { network, contractAddress, tokenId } = req.params;
   139→
   140→      const nft = await videoNFTService.getVideoNFT(
   141→        contractAddress,
   142→        parseInt(tokenId),
   143→        network
   144→      );
   145→
   146→      res.json(nft);
   147→
   148→    } catch (error: any) {
   149→      console.error("Failed to get video NFT:", error);
   150→      res.status(500).json({
   151→        error: "Failed to get video NFT",
   152→        message: error.message
   153→      });
   154→    }
   155→  });
   156→
   157→  /**
   158→   * Complete release package: Audio + Video + NFTs
   159→   * POST /api/publish/complete-package
   160→   */
   161→  app.post("/api/publish/complete-package", upload.single("audio"), async (req: Request, res: Response) => {
   162→    try {
   163→      const audioPath = req.file?.path || req.body.audioPath;
   164→      if (!audioPath) {
   165→        return res.status(400).json({ error: "Audio file required" });
   166→      }
   167→
   168→      const {
   169→        songId,
   170→        title,
   171→        artist,
   172→        description,
   173→        genre,
   174→        network,
   175→        walletId,
   176→        generateVideo = true,
   177→        generateVisualizer = true,
   178→        mintAudioNFT = true,
   179→        mintVideoNFT = true,
   180→        createToken = true,
   181→        tokenSupply = "1000000",
   182→        comfyui_url
   183→      } = req.body;
   184→
   185→      if (!title || !artist || !network || !walletId) {
   186→        return res.status(400).json({
   187→          error: "Missing required fields: title, artist, network, walletId"
   188→        });
   189→      }
   190→
   191→      const results: any = {
   192→        songId,
   193→        title,
   194→        artist,
   195→        audio: { path: audioPath },
   196→        video: null,
   197→        visualizer: null,
   198→        nfts: [],
   199→        token: null,
   200→        ipfs: [],
   201→        errors: []
   202→      };
   203→
   204→      // Step 1: Generate music video if requested
   205→      if (generateVideo) {
   206→        try {
   207→          console.log("[Package] Generating music video...");
   208→          const videoJob = await visualizerService.generateVideo(audioPath, {
   209→            style: "music_video",
   210→            genre,
   211→            artist,
   212→            title,
   213→            comfyui_url
   214→          });
   215→
   216→          // Wait for completion (with timeout)
   217→          let attempts = 0;
   218→          const maxAttempts = 180; // 30 minutes (10s intervals)
   219→
   220→          while (attempts < maxAttempts) {
   221→            const status = visualizerService.getJobStatus(videoJob.job_id);
   222→            if (status?.status === "completed" && status.video_path) {
   223→              results.video = {
   224→                job_id: videoJob.job_id,
   225→                path: status.video_path,
   226→                prompts: status.prompts
   227→              };
   228→              break;
   229→            } else if (status?.status === "failed") {
   230→              results.errors.push(`Video generation failed: ${status.error}`);
   231→              break;
   232→            }
   233→
   234→            await new Promise(resolve => setTimeout(resolve, 10000)); // Wait 10s
   235→            attempts++;
   236→          }
   237→
   238→          if (attempts >= maxAttempts) {
   239→            results.errors.push("Video generation timed out");
   240→          }
   241→
   242→        } catch (error: any) {
   243→          results.errors.push(`Video generation error: ${error.message}`);
   244→        }
   245→      }
   246→
   247→      // Step 2: Generate visualizer if requested
   248→      if (generateVisualizer) {
   249→        try {
   250→          console.log("[Package] Generating visualizer...");
   251→          const visualizerJob = await visualizerService.generateVideo(audioPath, {
   252→            style: "visualizer",
   253→            genre,
   254→            artist,
   255→            title,
   256→            comfyui_url
   257→          });
   258→
   259→          // Similar waiting logic as video
   260→          // (simplified for brevity - would be same as above)
   261→          results.visualizer = {
   262→            job_id: visualizerJob.job_id,
   263→            status: "queued"
   264→          };
   265→
   266→        } catch (error: any) {
   267→          results.errors.push(`Visualizer generation error: ${error.message}`);
   268→        }
   269→      }
   270→
   271→      // Step 3: Mint audio NFT
   272→      if (mintAudioNFT) {
   273→        try {
   274→          console.log("[Package] Would mint audio NFT (requires song in storage)...");
   275→          // In production, first store song, then call:
   276→          // await jesusCartelService.publishSong(songId, walletId, { mintNFT: true, network })
   277→
   278→          results.nfts.push({
   279→            type: "audio",
   280→            status: "pending",
   281→            message: "Audio NFT minting queued"
   282→          });
   283→
   284→        } catch (error: any) {
